func buildCanonicalPageNameMap(pages []planPageRow, logger *zap.Logger) map[string]string {
	m := make(map[string]string, len(pages)*3)
	for _, p := range pages { if p.Name != "" { m[p.Name] = p.Name } }   // Pass 1: identity
	// Pass 2: aliases. ambiguous tracks keys claimed by two different targets.
	ambiguous := map[string]bool{}
	for _, p := range pages {
		for _, alias := range []string{normalisePageKey(p.RawName), normalisePageKey(p.Name)} {
			if alias == "" || alias == p.Name { continue }
			if existing, taken := m[alias]; taken && existing != p.Name { ambiguous[alias] = true; continue }
			m[alias] = p.Name
		}
	}
	for alias := range ambiguous { delete(m, alias) }   // a confident wrong rewrite is worse than none
	return m
}

